insert into public.recettes (id, nom, categorie, portions, temps, instructions, prix_vente_ht) values
 ('00000000-0000-4000-8000-000000000201', 'Poulet braisé & attiéké', 'Grillades', 4, 90, 'Mariner le poulet (ail, gingembre, piment, cube) 2 h. Braiser au feu de bois en retournant régulièrement. Servir avec l''attiéké, la sauce tomate-oignon et un citron.', 7500),
 ('00000000-0000-4000-8000-000000000202', 'Sauce graine', 'Sauces & plats', 6, 75, 'Faire bouillir les graines de palme puis les écraser et tamiser pour obtenir le jus. Mijoter le jus avec aubergines, tomate, oignon, poisson et épices 45 min jusqu''à consistance nappante.', 3000),
 ('00000000-0000-4000-8000-000000000203', 'Garba thon', 'Street food', 4, 30, 'Frire le thon en tranches épaisses, bien doré. Servir généreusement sur l''attiéké avec rondelles d''oignon et de tomate, mayonnaise et piment.', 2500),
 ('00000000-0000-4000-8000-000000000204', 'Alloco', 'Accompagnements', 4, 25, 'Éplucher et couper les plantains mûrs en biseaux. Frire à l''huile chaude jusqu''à coloration dorée. Saler légèrement, accompagner de sauce piment-tomate.', 1500)
